  const CON = '#cfcabf', CP = '#45494c', GRN = '#557a43', DECK = '#b8b3a6', POOL = {c:'#4aa3c8', glow:'#3fb4ff', gk:0.35}, CRT = GRN, ROOF = '#6f757a';
