    const onCurve = i => curve.includes(i) && curve.includes((i + 1) % P.length);
    mullP(B.p(FIN), P, 0, (x, z) => roof(x, z) - 0.2, 2.4, 0.22, 0.35, onCurve);
    mullP(B.p(FIN), P, 0, (x, z) => roof(x, z) - 0.2, 1.6, 0.12, 0.12, i => !onCurve(i));
    // the sail screen: the curved glass runs on above the roof, highest at the mast, with a lit top edge
    const C = curve.map(i => P[i]), top = (x, z) => roof(x, z) + scrH*(1 - 0.6*sOf(x, z));
