  // green walls on the long faces
  { const gr = B.p(GRN); const Fs = facesP(P); for (const Fa of Fs) if (Fa.L > 12) for (let u = 2; u < Fa.L - 6; u += 9) if (rng() < 0.7) frect(gr, Fa, u, u + 6, 5.5, H - 2, 0.12); }
